JavaScript function "streamExpand"
in Projects/delta-ai-extension/background.js
Purpose: streamExpand(tabId, frameId, requestId, selection, context), authorization, error handling, HTTP/API, file operations, configuration

async function streamExpand(tabId, frameId, requestId, selection, context, prompt) {
  abortStream(requestId);

  const config = await loadConfig();
  const messages = [
    { role: 'system', content: getSystemPrompt('lookup') },
    ...buildExpandMessages({ answer: context, selection, prompt })
  ];

  const ac = new AbortController();
  activeStreams.set(requestId, ac);

  try {
    let fullResponse = '';
    for await (const chunk of callProviderStream(messages, config)) {
      if (ac.signal.aborted) break;
      fullResponse += chunk;
      try {
        await browser.tabs.sendMessage(tabId, {
          type: 'expandChunk',
          requestId,
          text: fullResponse,
          done: false
        }, { frameId });
      } catch {
        break;
      }
    }

    if (!ac.signal.aborted) {
      try {
        await browser.tabs.sendMessage(tabId, {
          type: 'expandChunk',
          requestId,
          text: fullResponse,
          done: true
        }, { frameId });
      } catch { /* tab gone */ }
    }
  } catch (err) {
    try {
      await browser.tabs.sendMessage(tabId, {
        type: 'expandChunk',
        requestId,
        error: err?.message || 'Unknown error',
        done: true
      }, { frameId });
    } catch { /* tab gone */ }
  } finally {
    activeStreams.delete(requestId);
  }
}

