Purpose: fetchWithTimeout(url, options), validation, error handling, HTTP/API, configuration, routing/middleware

async function fetchWithTimeout(url, options) {
  const timeout = options.timeout ?? FETCH_TIMEOUT_MS;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  try {
    const res = await fetch(url, { ...options, signal: controller.signal });
    return res;
  } catch (err) {
    if (err.name === 'AbortError') {
      throw new Error(`Request timed out after ${timeout / 1000}s. Check your API endpoint and network connection.`);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

